const b = ($input.first().json.body) || {};
const mode = ['search', 'urgent', 'all', 'route'].includes(b.mode) ? b.mode : null;
const num = v => (v === null || v === undefined || v === '') ? NaN : Number(v);
const okPt = (la, lo) => isFinite(la) && isFinite(lo) && Math.abs(la) <= 90 && Math.abs(lo) <= 180;
if (!mode) return [{ json: { mode: 'error', error: 'invalid mode' } }];

if (mode === 'route') {
  const f = b.from || {}, t = b.to || {};
  const from = { lat: num(f.lat), lng: num(f.lng) }, to = { lat: num(t.lat), lng: num(t.lng) };
  if (!okPt(from.lat, from.lng) || !okPt(to.lat, to.lng)) return [{ json: { mode: 'error', error: 'invalid from/to' } }];
  return [{ json: { mode, from, to, profile: b.profile === 'foot' ? 'foot' : 'driving' } }];
}
const lat = num(b.lat), lng = num(b.lng);
if (mode !== 'all' && !okPt(lat, lng)) return [{ json: { mode: 'error', error: 'invalid lat/lng' } }];
return [{ json: {
  mode, lat, lng,
  radius: Math.min(Math.max(Number(b.radius) || 3000, 500), 20000),
  type: ['hospital', 'clinic', 'birth', 'rabies'].includes(b.type) ? b.type : null,
  refresh: b.refresh === true, approximate: b.approximate === true,
} }];

const req = $input.first().json;
const { from, to, profile } = req;
const rad = x => x * Math.PI / 180;
const dist = (a, b, c, d) => {
  const h = Math.sin(rad(c - a) / 2) ** 2 + Math.cos(rad(a)) * Math.cos(rad(c)) * Math.sin(rad(d - b) / 2) ** 2;
  return 2 * 6371000 * Math.asin(Math.sqrt(h));
};

// ---- cache (10 min, rounded to ~11 m) ----
const store = $getWorkflowStaticData('global');
store.routes = store.routes || {};
const key = [profile, from.lat.toFixed(4), from.lng.toFixed(4), to.lat.toFixed(4), to.lng.toFixed(4)].join('|');
const hit = store.routes[key];
if (hit && Date.now() - hit.at < 600000) return [{ json: { ...hit.data, cache: 'hit' } }];

// ---- providers in order; first good answer wins ----
const coords = `${from.lng},${from.lat};${to.lng},${to.lat}`;
const qs = 'overview=full&geometries=geojson&steps=true&alternatives=false';
const providers = profile === 'foot'
  ? [`https://routing.openstreetmap.de/routed-foot/route/v1/driving/${coords}?${qs}`]
  : [`https://routing.openstreetmap.de/routed-car/route/v1/driving/${coords}?${qs}`,
     `https://router.project-osrm.org/route/v1/driving/${coords}?${qs}`];

let route = null, source = '', lastErr = '';
for (let round = 0; round < 2 && !route; round++) {
  for (const url of providers) {
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url, json: true, timeout: 15000, headers: { 'User-Agent': 'caloocan-health-finder/1.0' } });
      if (r && r.code === 'Ok' && r.routes && r.routes[0] && r.routes[0].geometry) { route = r.routes[0]; source = url.split('/')[2]; break; }
      lastErr = 'code ' + (r && r.code);
    } catch (e) { lastErr = String(e.message || e); }
  }
}

let out;
if (route) {
  const steps = route.legs[0].steps
    .filter(s => s.distance > 0 || s.maneuver.type === 'arrive')
    .map(s => ({ type: s.maneuver.type, modifier: s.maneuver.modifier || '', name: s.name || '', distance_m: Math.round(s.distance), at: s.maneuver.location }));
  // OSRM gives free-flow time. Metro Manila traffic: x1.6 for car; walking left as is.
  const factor = profile === 'foot' ? 1 : 1.6;
  out = {
    ok: true, approx: false, profile, source,
    distance_m: Math.round(route.distance),
    duration_s: Math.round(route.duration * factor), duration_free_s: Math.round(route.duration),
    geometry: route.geometry, steps,
    end: { snapped_m: Math.round(dist(to.lat, to.lng, route.geometry.coordinates.at(-1)[1], route.geometry.coordinates.at(-1)[0])) },
  };
} else {
  // every provider failed → straight line so the UI still shows something, flagged approximate
  const d = dist(from.lat, from.lng, to.lat, to.lng);
  const speed = profile === 'foot' ? 1.3 : 4.2; // m/s
  out = {
    ok: true, approx: true, profile, source: 'straight-line', warning: lastErr,
    distance_m: Math.round(d * 1.3), duration_s: Math.round(d * 1.3 / speed),
    geometry: { type: 'LineString', coordinates: [[from.lng, from.lat], [to.lng, to.lat]] },
    steps: [{ type: 'arrive', modifier: '', name: '', distance_m: Math.round(d), at: [to.lng, to.lat] }],
  };
}
if (!out.approx) {
  store.routes[key] = { at: Date.now(), data: out };
  const ks = Object.keys(store.routes);
  if (ks.length > 200) ks.sort((a, b) => store.routes[a].at - store.routes[b].at).slice(0, ks.length - 200).forEach(k => delete store.routes[k]);
}
return [{ json: { ...out, cache: 'miss' } }];

const req = $input.first().json;
const rad = x => x * Math.PI / 180;
const dist = (a, b, c, d) => {
  const h = Math.sin(rad(c - a) / 2) ** 2 + Math.cos(rad(a)) * Math.cos(rad(c)) * Math.sin(rad(d - b) / 2) ** 2;
  return 2 * 6371000 * Math.asin(Math.sqrt(h));
};
const classify = t => {
  const n = [t.name, t['name:en'], t.description].filter(Boolean).join(' ');
  if (/rabies|animal bite|abtc|anti-?rabies/i.test(n) || t['healthcare:speciality'] === 'animal_bite') return 'rabies';
  if (t.healthcare === 'birth_centre' || /lying[- ]?in|maternity|paanakan|birthing|midwi/i.test(n)) return 'birth';
  if (t.amenity === 'hospital' || t.healthcare === 'hospital') return 'hospital';
  return 'clinic';
};

// ---- 1. Load ALL Caloocan facilities (cached 24h in workflow static data) ----
const store = $getWorkflowStaticData('global');
const TTL = 24 * 3600 * 1000;
let cacheState = 'hit';
if (!store.places || !store.at || Date.now() - store.at > TTL || req.refresh === true) {
  const bbox = '14.60,120.93,14.78,121.09';   // all of Caloocan (North + South)
  const query = `[out:json][timeout:60];(
    nwr(${bbox})[amenity~"^(hospital|clinic|doctors)$"];
    nwr(${bbox})[healthcare~"^(hospital|clinic|birth_centre|doctor)$"];
    nwr(${bbox})[name~"rabies|animal bite|lying|maternity|paanakan|birthing",i];
  );out center tags;`;
  const mirrors = ['https://overpass-api.de/api/interpreter', 'https://overpass.kumi.systems/api/interpreter', 'https://overpass.private.coffee/api/interpreter'];
  let elements = null, lastErr = '';
  for (let round = 0; round < 2 && !elements; round++) {
    for (const url of mirrors) {
      try {
        const r = await this.helpers.httpRequest({
          method: 'POST', url, json: true, timeout: 70000,
          headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'User-Agent': 'caloocan-health-finder/1.0 (khent.agustin@247ga.co)' },
          body: 'data=' + encodeURIComponent(query),
        });
        if (r && Array.isArray(r.elements) && r.elements.length > 0 && !r.remark) { elements = r.elements; break; }
        lastErr = 'empty/remark: ' + (r && r.remark);
      } catch (e) { lastErr = String(e.message || e); }
    }
  }
  if (!elements) {
    if (store.places) cacheState = 'stale';          // serve old data rather than fail
    else return [{ json: { ok: false, error: 'map data unavailable', detail: lastErr } }];
  } else {
    let list = [];
    for (const e of elements) {
      const t = e.tags || {};
      const la = e.lat ?? (e.center && e.center.lat), lo = e.lon ?? (e.center && e.center.lon);
      const name = t.name || t['name:en'];
      if (la == null || !name) continue;
      const type = classify(t);
      list.push({
        id: e.type + e.id, name, type, lat: la, lng: lo,
        emergency: type === 'hospital' && t.emergency !== 'no',
        phone: (t.phone || t['contact:phone'] || '').split(';')[0].trim(),
        website: t.website || t['contact:website'] || '',
        hours: t.opening_hours || '',
        address: [t['addr:housenumber'], t['addr:street'], t['addr:suburb'] || t['addr:barangay']].filter(Boolean).join(' '),
      });
    }
    // dedupe: same name within 120 m
    const kept = [];
    for (const p of list) {
      if (!kept.find(k => k.name.toLowerCase() === p.name.toLowerCase() && dist(k.lat, k.lng, p.lat, p.lng) < 120)) kept.push(p);
    }
    store.places = kept; store.at = Date.now(); cacheState = 'refreshed';
  }
}
const all = store.places;
const counts = all.reduce((m, p) => (m[p.type] = (m[p.type] || 0) + 1, m), {});
return [{ json: { req, all, meta: { cache: cacheState, cachedAt: new Date(store.at).toISOString(), total: all.length, counts } } }];

const { req, all, meta } = $input.first().json;
const { mode, lat, lng } = req;
const rad = x => x * Math.PI / 180;
const dist = (a, b, c, d) => {
  const h = Math.sin(rad(c - a) / 2) ** 2 + Math.cos(rad(a)) * Math.cos(rad(c)) * Math.sin(rad(d - b) / 2) ** 2;
  return 2 * 6371000 * Math.asin(Math.sqrt(h));
};
if (mode === 'all') return [{ json: { ok: true, mode, ...meta, places: all } }];

const withDist = all.map(p => {
  const d = dist(lat, lng, p.lat, p.lng);
  return { ...p, distance_m: Math.round(d), eta_min: Math.max(1, Math.round((d * 1.35 * 1.6) / 333)) };
}).sort((a, b) => a.distance_m - b.distance_m);

if (mode === 'urgent') {
  const hospitals = withDist.filter(p => p.type === 'hospital' && p.emergency);
  const best = hospitals[0] || null;
  const message = best
    ? `🚨 URGENT — Caloocan Health Finder\nUser: https://www.google.com/maps?q=${lat},${lng}${req.approximate ? ' (approximate)' : ''}\nNearest hospital: ${best.name} (${best.distance_m} m, ~${best.eta_min} min)\nPhone: ${best.phone || 'n/a'}\nTime: ${new Date().toISOString()}`
    : `🚨 URGENT — no hospital found near ${lat},${lng}. Advise calling 911.`;
  return [{ json: { ok: true, mode, ...meta, nearest: best, alternatives: hospitals.slice(1, 4), message } }];
}
const places = withDist.filter(p => p.distance_m <= req.radius && (!req.type || p.type === req.type));
return [{ json: { ok: true, mode, radius: req.radius, ...meta, count: places.length, places } }];
